  assign CLK_DISTR_OUT_LEFT_P = CLK_DISTR_OUT_LEFT_P_out;
  assign CLK_DISTR_OUT_RIGHT_P = CLK_DISTR_OUT_RIGHT_P_out;
  assign CLK_DISTR_OUT_RIGHT_PLL_P = CLK_DISTR_OUT_RIGHT_PLL_P_out;
  assign CLK_DISTR_OUT_RIGHT_T1_P = CLK_DISTR_OUT_RIGHT_T1_P_out;
  assign CSA_CAL_CONTROL_DAC0 = CSA_CAL_CONTROL_DAC0_out;
  assign CSA_CAL_CONTROL_DAC1 = CSA_CAL_CONTROL_DAC1_out;
  assign CSA_CAL_CONTROL_DAC2 = CSA_CAL_CONTROL_DAC2_out;
  assign CSA_CAL_CONTROL_DAC3 = CSA_CAL_CONTROL_DAC3_out;
  assign CSA_CAL_DATA_DAC0 = CSA_CAL_DATA_DAC0_out;
  assign CSA_CAL_DATA_DAC1 = CSA_CAL_DATA_DAC1_out;
  assign CSA_CAL_DATA_DAC2 = CSA_CAL_DATA_DAC2_out;
  assign CSA_CAL_DATA_DAC3 = CSA_CAL_DATA_DAC3_out;
  assign PLL_DMON_OUT = PLL_DMON_OUT_out;
  assign PLL_DMON_OUT_SPARE = PLL_DMON_OUT_SPARE_out;
  assign PRDATA = PRDATA_out;
  assign PREADY = PREADY_out;
  assign PSLVERR = PSLVERR_out;
  assign STATUS_COMMON = STATUS_COMMON_out;
  assign STATUS_DAC0 = STATUS_DAC0_out;
  assign STATUS_DAC1 = STATUS_DAC1_out;
  assign STATUS_DAC2 = STATUS_DAC2_out;
  assign STATUS_DAC3 = STATUS_DAC3_out;
  assign SYSREF_OUT1_R_P = SYSREF_OUT1_R_P_out;
  assign SYSREF_OUT2_R_P = SYSREF_OUT2_R_P_out;
  assign SYSREF_OUT_L_P = SYSREF_OUT_L_P_out;
  assign TM_CAL_CONTROL_DAC0 = TM_CAL_CONTROL_DAC0_out;
  assign TM_CAL_CONTROL_DAC1 = TM_CAL_CONTROL_DAC1_out;
  assign TM_CAL_CONTROL_DAC2 = TM_CAL_CONTROL_DAC2_out;
  assign TM_CAL_CONTROL_DAC3 = TM_CAL_CONTROL_DAC3_out;
  assign TM_CAL_DATA_DAC0 = TM_CAL_DATA_DAC0_out;
  assign TM_CAL_DATA_DAC1 = TM_CAL_DATA_DAC1_out;
  assign TM_CAL_DATA_DAC2 = TM_CAL_DATA_DAC2_out;
  assign TM_CAL_DATA_DAC3 = TM_CAL_DATA_DAC3_out;
  assign VOUT0_N = VOUT0_N_out;
  assign VOUT0_P = VOUT0_P_out;
  assign VOUT1_N = VOUT1_N_out;
  assign VOUT1_P = VOUT1_P_out;
  assign VOUT2_N = VOUT2_N_out;
  assign VOUT2_P = VOUT2_P_out;
  assign VOUT3_N = VOUT3_N_out;
  assign VOUT3_P = VOUT3_P_out;

`ifdef XIL_TIMING
  assign CONTROL_COMMON_in = CONTROL_COMMON_delay;
  assign CONTROL_DAC0_in = CONTROL_DAC0_delay;
  assign CONTROL_DAC1_in = CONTROL_DAC1_delay;
  assign CONTROL_DAC2_in = CONTROL_DAC2_delay;
  assign CONTROL_DAC3_in = CONTROL_DAC3_delay;
  assign DATA_DAC0_in = DATA_DAC0_delay;
  assign DATA_DAC1_in = DATA_DAC1_delay;
  assign DATA_DAC2_in = DATA_DAC2_delay;
  assign DATA_DAC3_in = DATA_DAC3_delay;
  assign FABRIC_CLK_IO_in[0] = FABRIC_CLK_IO_delay[0];
  assign FABRIC_CLK_IO_in[1] = FABRIC_CLK_IO_delay[1];
  assign FABRIC_CLK_IO_in[2] = FABRIC_CLK_IO_delay[2];
  assign FABRIC_CLK_IO_in[3] = FABRIC_CLK_IO_delay[3];
  assign FABRIC_CLK_in = FABRIC_CLK_delay;
  assign PADDR_in = PADDR_delay;
  assign PCLK_in = PCLK_delay;
  assign PENABLE_in = PENABLE_delay;
  assign PSEL_in = PSEL_delay;
  assign PWDATA_in = PWDATA_delay;
  assign PWRITE_in = PWRITE_delay;
`else
  assign CONTROL_COMMON_in = CONTROL_COMMON;
  assign CONTROL_DAC0_in = CONTROL_DAC0;
  assign CONTROL_DAC1_in = CONTROL_DAC1;
  assign CONTROL_DAC2_in = CONTROL_DAC2;
  assign CONTROL_DAC3_in = CONTROL_DAC3;
  assign DATA_DAC0_in = DATA_DAC0;
  assign DATA_DAC1_in = DATA_DAC1;
  assign DATA_DAC2_in = DATA_DAC2;
  assign DATA_DAC3_in = DATA_DAC3;
  assign FABRIC_CLK_IO_in[0] = FABRIC_CLK_IO[0];
  assign FABRIC_CLK_IO_in[1] = FABRIC_CLK_IO[1];
  assign FABRIC_CLK_IO_in[2] = FABRIC_CLK_IO[2];
  assign FABRIC_CLK_IO_in[3] = FABRIC_CLK_IO[3];
  assign FABRIC_CLK_in = FABRIC_CLK;
