`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((SIM_DEVICE_REG != "VERSAL") &&
         (SIM_DEVICE_REG != "VERSAL_ES1") &&
         (SIM_DEVICE_REG != "VERSAL_ES2"))) begin
      $display("Error: [Unisim %s-102] SIM_DEVICE attribute is set to %s.  Legal values for this attribute are VERSAL, VERSAL_ES1 or VERSAL_ES2. Instance: %m", MODULE_NAME, SIM_DEVICE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_ACTIVE_DUTYCYCLE_REG < 0) || (XPA_ACTIVE_DUTYCYCLE_REG > 100))) begin
      $display("Error: [Unisim %s-103] XPA_ACTIVE_DUTYCYCLE attribute is set to %d.  Legal values for this attribute are 0 to 100. Instance: %m", MODULE_NAME, XPA_ACTIVE_DUTYCYCLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_CHANNELIZER_ENABLE_REG < 0) || (XPA_CHANNELIZER_ENABLE_REG > 2))) begin
      $display("Error: [Unisim %s-104] XPA_CHANNELIZER_ENABLE attribute is set to %d.  Legal values for this attribute are 0 to 2. Instance: %m", MODULE_NAME, XPA_CHANNELIZER_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_CHANNELS_PER_TILE_REG < 0) || (XPA_CHANNELS_PER_TILE_REG > 4))) begin
      $display("Error: [Unisim %s-105] XPA_CHANNELS_PER_TILE attribute is set to %d.  Legal values for this attribute are 0 to 4. Instance: %m", MODULE_NAME, XPA_CHANNELS_PER_TILE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_CLOCK_SOURCE_REG < 0) || (XPA_CLOCK_SOURCE_REG > 2))) begin
      $display("Error: [Unisim %s-106] XPA_CLOCK_SOURCE attribute is set to %d.  Legal values for this attribute are 0 to 2. Instance: %m", MODULE_NAME, XPA_CLOCK_SOURCE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_DATAPATH_MODE_REG < 0) || (XPA_DATAPATH_MODE_REG > 3))) begin
      $display("Error: [Unisim %s-107] XPA_DATAPATH_MODE attribute is set to %d.  Legal values for this attribute are 0 to 3. Instance: %m", MODULE_NAME, XPA_DATAPATH_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_INTERPOLATION_REG < 0) || (XPA_INTERPOLATION_REG > 15))) begin
      $display("Error: [Unisim %s-108] XPA_INTERPOLATION attribute is set to %d.  Legal values for this attribute are 0 to 15. Instance: %m", MODULE_NAME, XPA_INTERPOLATION_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_MIXING_REG < 0) || (XPA_MIXING_REG > 3))) begin
      $display("Error: [Unisim %s-109] XPA_MIXING attribute is set to %d.  Legal values for this attribute are 0 to 3. Instance: %m", MODULE_NAME, XPA_MIXING_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_NUMBER_OF_DUC_REG < 0) || (XPA_NUMBER_OF_DUC_REG > 8))) begin
      $display("Error: [Unisim %s-110] XPA_NUMBER_OF_DUC attribute is set to %d.  Legal values for this attribute are 0 to 8. Instance: %m", MODULE_NAME, XPA_NUMBER_OF_DUC_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_PFIR_CHANNELIZER_LOCATION_REG < 0) || (XPA_PFIR_CHANNELIZER_LOCATION_REG > 1))) begin
      $display("Error: [Unisim %s-111] XPA_PFIR_CHANNELIZER_LOCATION attribute is set to %d.  Legal values for this attribute are 0 to 1. Instance: %m", MODULE_NAME, XPA_PFIR_CHANNELIZER_LOCATION_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_PFIR_TAPS_REG < 0) || (XPA_PFIR_TAPS_REG > 100))) begin
      $display("Error: [Unisim %s-112] XPA_PFIR_TAPS attribute is set to %d.  Legal values for this attribute are 0 to 100. Instance: %m", MODULE_NAME, XPA_PFIR_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_QMC_TAPS_REG < 0) || (XPA_QMC_TAPS_REG > 100))) begin
      $display("Error: [Unisim %s-113] XPA_QMC_TAPS attribute is set to %d.  Legal values for this attribute are 0 to 100. Instance: %m", MODULE_NAME, XPA_QMC_TAPS_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_SAMPLE_RATE_REG < 0) || (XPA_SAMPLE_RATE_REG > 16000))) begin
      $display("Error: [Unisim %s-114] XPA_SAMPLE_RATE attribute is set to %d.  Legal values for this attribute are 0 to 16000. Instance: %m", MODULE_NAME, XPA_SAMPLE_RATE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((XPA_SPARE_REG < 0) || (XPA_SPARE_REG > 100))) begin
      $display("Error: [Unisim %s-115] XPA_SPARE attribute is set to %d.  Legal values for this attribute are 0 to 100. Instance: %m", MODULE_NAME, XPA_SPARE_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif



assign SCAN_CHNL_IN_EXT_in = 15'b111111111111111; // tie off
assign SCAN_CLK_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_CNTRL_CHNL_IN_EXT_in = 1'b1; // tie off
assign SCAN_EDT_UPDT_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_EN_N_IN_EXT_in = 1'b1; // tie off
assign SCAN_MODE_RST_N_IN_EXT_in = 1'b1; // tie off

  SIP_RFDACE5 #(
    .MEMORY_INIT_FILE (MEMORY_INIT_FILE)
